ue:sku::STRING, \'-\', 3) WHEN POSITION(\'-\' IN value:sku::STRING) > 0 THEN SPLIT_PART(value:sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 2) ELSE value:sku::STRING END AS sku_group, MIN(PUBLISHEDAT::DATE) AS live_date, LOWER(status) AS status, legacyresourceid AS id, UPPER(title) AS product_name FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value GROUP BY 1, 3,4,5 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, a.id, a.product_name, live_date, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), live_date_last_check as ( select sku_group, status, trim(id) as id, product_name, live_date from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), first_order_date as ( select sku_group, min(order_timestamp::date) as first_order_date from snitch_db.maplemonk.fact_items_snitch group by 1 ), live_date_final_calculated as ( select a.sku_group, a.status, a.id, a.product_name, case when a.live_date is null and b.first_order_date is not null then b.first_order_date when b.first_order_date is null and a.live_date is not null then a.live_date else least(a.live_date,b.first_order_date) end as live_date from live_date_last_check a left join first_order_date b on a.sku_group = b.sku_group ), price2 as ( SELECT CASE WHEN upper(value:sku::STRING) LIKE \'4C-%\' THEN SPLIT_PART(value:sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 2) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 3) WHEN upper(value:sku::STRING) LIKE \'MP-%\' THEN SPLIT_PART(value:sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 2) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 3) WHEN POSITION(\'-\' IN value:sku::STRING) > 0 THEN SPLIT_PART(value:sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 2) ELSE value:sku::STRING END AS sku_group, VARIANT.value:compare_at_price::integer as cp_price, VARIANT.value:price::integer as price FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT ), final_price_pre as ( select distinct upper(trim(sku_group)) as sku_group, case when cp_price is null or cp_price = 0 then price else cp_price end as original_price, price as current_slashed_price from price2 ), final_price_adj as ( select sku_group, max(original_price) as original_price, max(current_slashed_price) as current_slashed_price from final_price_pre group by 1 ), price as ( select sku_group, case when current_slashed_price >= original_price then current_slashed_price else original_price end as original_price, current_slashed_price from final_price_adj ), category as ( SELECT trim(id) as id, producttype as category FROM ( SELECT SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\')) AS id, producttype, ROW_NUMBER() OVER (PARTITION BY SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\'))ORDER BY REPLACE(A.value:updated_at, \'\"\', \'\')DESC ) AS rw FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql , LATERAL FLATTEN (input => metafields) A ) WHERE rw = 1 ), live_date_final as ( select a.*, b.category from live_date_final_calculated a left join category b on a.id = b.id ), on_hold as ( select sku_group, size, sum(quantity) as quantiity from snitch_db.maplemonk.fact_items_snitch where tags like \'%eco-exchange-hold%\' and tags like \'%Snitch-RMS-Exchange for%\' and order_timestamp::date > current_date - 90 group by 1,2 ), snitch_final_inventory_wh2_pre as ( select CASE WHEN upper(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN upper(\"Item SkuCode\") LIKE \'MP-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS sku_group, REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\', REVERSE(\"Item SkuCode\")) - 1)) as size, sum(inventory) as inventory from snitch_db.maplemonk.unicommerce_live_inventory WHERE facility in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\') GROUP BY 1,2 ), snitch_final_inventory_wh2 as ( select a.*, coalesce(b.quantiity,0) as hold_quantity, greatest(a.inventory-coalesce(b.quantiity,0),0) as final_quantity from snitch_final_inventory_wh2_pre a left join on_hold b on a.sku_group = b.sku_group and a.size = b.size ), pivot_table_pre as ( SELECT sku_group, sum(final_quantity) AS Sellable_Inventory, COALESCE(SUM(CASE WHEN size IN (\'4MSF\', \'4MAC\', \'SH01\', \'4MBL\', \'SH00\', \'BP00\', \'SN00\') THEN final_quantity ELSE 0 END), 0) AS NA_units, COALESCE(SUM(CASE WHEN (size = \'XS\' OR size = \'28\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'40\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN (size = \'S\' OR size = \'30\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'41\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN (size = \'M\' OR size = \'32\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'42\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN (size = \'L\' OR size = \'34\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'43\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN (size = \'XL\' OR size = \'36\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'44