\', 1) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 2) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 3) WHEN POSITION(\'-\' IN value:sku::STRING) > 0 THEN SPLIT_PART(value:sku::STRING, \'-\', 1) || \'-\' || SPLIT_PART(value:sku::STRING, \'-\', 2) ELSE value:sku::STRING END AS sku_group, VARIANT.value:compare_at_price::integer as cp_price, VARIANT.value:price::integer as price FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT ), final_price_pre as ( select distinct upper(trim(sku_group)) as sku_group, case when cp_price is null or cp_price = 0 then price else cp_price end as original_price, price as current_slashed_price from price2 ), final_price_adj as ( select sku_group, max(original_price) as original_price, max(current_slashed_price) as current_slashed_price from final_price_pre group by 1 ), price as ( select sku_group, case when current_slashed_price >= original_price then current_slashed_price else original_price end as original_price, current_slashed_price from final_price_adj ), category as ( SELECT trim(id) as id, producttype as category FROM ( SELECT SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\')) AS id, producttype, ROW_NUMBER() OVER (PARTITION BY SUBSTRING(id, POSITION(\'Product/\' IN id) + LENGTH(\'Product/\'))ORDER BY REPLACE(A.value:updated_at, \'\"\', \'\')DESC ) AS rw FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql , LATERAL FLATTEN (input => metafields) A ) WHERE rw = 1 ), live_date_final as ( select a.*, b.category from live_date_final_calculated a left join category b on a.id = b.id ), on_hold as ( select sku_group, size, sum(quantity) as quantiity from snitch_db.maplemonk.fact_items_snitch where tags like \'%eco-exchange-hold%\' and tags like \'%Snitch-RMS-Exchange for%\' and order_timestamp::date > current_date - 90 group by 1,2 ), snitch_final_inventory_wh2_pre as ( select CASE WHEN upper(\"Item SkuCode\") LIKE \'4C-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN upper(\"Item SkuCode\") LIKE \'MP-%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS sku_group, REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\', REVERSE(\"Item SkuCode\")) - 1)) as size, sum(inventory) as inventory from snitch_db.maplemonk.unicommerce_live_inventory WHERE facility in (\'SAPL-NORTH-TAURU\') GROUP BY 1,2 ), snitch_final_inventory_wh2 as ( select a.*, coalesce(b.quantiity,0) as hold_quantity, greatest(a.inventory-coalesce(b.quantiity,0),0) as final_quantity from snitch_final_inventory_wh2_pre a left join on_hold b on a.sku_group = b.sku_group and a.size = b.size ), pivot_table_pre as ( SELECT sku_group, sum(final_quantity) AS Sellable_Inventory, COALESCE(SUM(CASE WHEN size IN (\'4MSF\', \'4MAC\', \'SH01\', \'4MBL\', \'SH00\', \'BP00\', \'SN00\') THEN final_quantity ELSE 0 END), 0) AS NA_units, COALESCE(SUM(CASE WHEN (size = \'XS\' OR size = \'28\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'40\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XS_units, COALESCE(SUM(CASE WHEN (size = \'S\' OR size = \'30\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'41\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS S_units, COALESCE(SUM(CASE WHEN (size = \'M\' OR size = \'32\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'42\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS M_units, COALESCE(SUM(CASE WHEN (size = \'L\' OR size = \'34\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'43\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS L_units, COALESCE(SUM(CASE WHEN (size = \'XL\' OR size = \'36\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'44\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XL_units, COALESCE(SUM(CASE WHEN (size IN (\'XXL\',\'XXl\',\'2XL\',\'38\') AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'45\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XXL_units, COALESCE(SUM(CASE WHEN (size = \'3XL\' OR size = \'40\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'46\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XL3_units, COALESCE(SUM(CASE WHEN (size = \'4XL\' OR size = \'42\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'47\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XL4_units, COALESCE(SUM(CASE WHEN (size = \'5XL\' OR size = \'44\' AND lower(sku_group) NOT LIKE \'sh%\') OR (size = \'48\' AND lower(sku_group) LIKE \'sh%\') THEN final_quantity ELSE 0 END), 0) AS XL5_units, COALESCE(SUM(CASE WHEN size = \'6XL\' OR size = \'46\' THEN final_quantity ELSE 0 END), 0) AS XL6_units, COALESCE(SUM(CASE WHEN size = \'7XL\' OR size = \'48\' THEN final_quantity ELSE 0 END), 0) AS XL7_units, COALESCE(SUM(CASE WHEN size = \'8XL\' OR size = \'50\' THEN final_quantity ELSE 0 END), 0) AS XL8_units FROM snitch_final_inventory_wh2 GROUP BY 1 ), PivotTable AS ( Select trim(upper(sku_group)) as sku_group, sum(Sellable_Inventory) as Sellable_Inventory, sum(XS_units) as XS_units, sum(S_units) as S_units, sum(M_units) as M_units, sum(L_units) as L_units, sum(XL_units) as XL_units, sum(XXL_units) as XXL_units, sum(XL3_units) as XL3_units, sum(XL4_units) as XL4_units, sum(XL5_units) as XL5_units, sum(XL6_units) as XL6_units, sum(XL7_units) as XL7_units, sum(XL8_units) as XL8_units, sum(NA_units) as NA_units from pivot_table_pre where lower(sku_group) not like\'cb%\' GROUP BY SKU_GROUP ), eoq_test_pre as ( select upper(trim(sku_group)) as sku_group, product_name, first_order_date, avg(final_ros) as final_ros, avg(eoq_new) as eoq_new, avg(total_units_on_hand) as total_units_on_hand, avg(op) as op, avg(natural_ros) as natural_ros, avg(sales_last_7_days) as sales_last_7_days, avg(sales_last_15_days) as sales_last_15_days, avg(sales_last_30_days) as sales_last_30_days from snitch_db.maplemonk.EOQ_Test where product_name is not null or product_name != \'\' group by 1,2,3 ) select coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group) as sku_group, product.id, price.original_price as price, price.current_slashed_price, product.product_name, case when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSS\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MST\' then \'T-Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSD\' then \'Jeans\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSW\' then \'Sweaters\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSO\' then \'Cargo Pants\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSK\' then \'Jackets\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MCR\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSR\' then \'Trousers\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),6) = \'4MBGSS\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),6) = \'4MBGSD\' then \'Jeans\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MTR\' then \'Cargo Pants\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),4) = \'4MSN\' then \'Shirts\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),2) = \'SN\' then \'Sunglasses\' when (product.category is null or product.category = \'\') and left(coalesce(PivotTable.SKU_GROUP,EOQ_Test.sku_group),2) = \'SH\' then \'Shoes\' else product.category end as category, EOQ_Test.final_ros, round(sum(coalesce(EOQ_Test.eoq_new,0)),0) as total_eoq, round(sum(coalesce(PivotTable.Sellable_Inventory,EOQ_Test.total_units_on_hand)),0) as available_units, round(sum(coalesce(EOQ_Test.op,0)),0) as order_point, EOQ_Test.natural_ros, EOQ_Test.sales_last_7_days, EOQ_Test.sales_last_15_days, EOQ_Test.sales_last_30_days, CASE WHEN EOQ_Test.final_ros >= 15 THEN \'1-Head\' WHEN EOQ_Test.final_ros < 15 AND EOQ_Test.final_ros >= 5 THEN \'2-Belly\' WHEN EOQ_Test.first_order_date > cast(getdate() as date)-45 THEN \'4-New\' WHEN EOQ_Test.first_order_date is not null and EOQ_Test.final_ros <5 then \'3-Tail\' WHEN EOQ_Test.first_order_date is null and product.status = \'active\' then \'4-New-Not-Sold\' WHEN EOQ_Test.first_order_date is null and product.status = \'draft\' then \'Draft\' WHEN product.status is null then \'Not-Cataloged\' ELSE \'Others\' END AS sku_class, PivotTable.Sellable_inventory, PivotTable.XS_units, PivotTable.S_units, PivotTable.M_units, PivotTable.L_units, PivotTable.XL_units, PivotTable.XXL_units, PivotTable.XL3_units, PivotTable.XL4_units, PivotTable.XL5_units, PivotTable.XL6_units, PivotTable.XL7_units, PivotTable.XL8_units, PivotTable.NA_units, (CASE WHEN PivotTable.XS_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.S_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.M_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.L_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XXL_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL3_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL4_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL5_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL6_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL7_units > 0 THEN 1 ELSE 0 END) + (CASE WHEN PivotTable.XL8_units > 0 THEN 1 ELSE 0 END) AS num_size_available, product.status, product.live_date, \'North\' as Warehouse_Location from PivotTable full outer join eoq_test_pre as EOQ_Test on PivotTable.sku_group = EOQ_Test.sku_group left join live_date_final as product on coalesce(PivotTable.sku_group,EOQ_Test.sku_group) = product.sku_group left join price as price on coalesce(PivotTable.sku_group,EOQ_Test.sku_group) = price.sku_group where COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group) != \'TEST_SNITCH\' and COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group) != \'GIFT\' group by COALESCE(PivotTable.SKU_GROUP, EOQ_Test.sku_group), product.id, price.original_price, price.current_slashed_price, product.product_name, product.category, EOQ_Test.final_ros, EOQ_Test.natural_ros, EOQ_Test.sales_last_7_days, EOQ_Test.sales_last_15_days, EOQ_Test.sales_last_30_days, EOQ_Test.first_order_date, product.status, PivotTable.Sellable_inventory, PivotTable.XS_units, PivotTable.S_units, PivotTable.M_units, PivotTable.L_units, PivotTable.XL_units, PivotTable.XXL_units, PivotTable.XL3_units, PivotTable.XL4_units, PivotTable.XL5_units, PivotTable.XL6_units, PivotTable.XL7_units, PivotTable.XL8_units, PivotTable.NA_units, product.live_date ); create or replace table snitch_db.maplemonk.availability_master_v2_Merged as select * from snitch_db.maplemonk.availability_master_v2_North union all select * from snitch_db.maplemonk.AVAILABILITY_MASTER_V2_SOUTH ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.AV_MASTER_HTMBASE AS WITH product_images AS ( SELECT sku_group, image_url FROM snitch_db.maplemonk.base_product ), metafields_std AS ( SELECT sku_group, product_name, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Graphic Print\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Graphic Print\' ELSE \'Others\' END WHEN UPPER(category) LIKE \'%SHIRTS%\' THEN CASE WHEN UPPER(TRIM(designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(designs)) = \'TEXTURED\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(designs)) = \'SELF DESIGN\' THEN \'Textured\' WHEN UPPER(TRIM(designs)) = \'PRINTED\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'OTHERS\' THEN \'Others\' WHEN UPPER(TRIM(designs)) = \'FLORAL\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'EMBROIDED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GEOMETRIC\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'TIE & DYE\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'EMBELLISHED\' THEN \'Embroided\' WHEN UPPER(TRIM(designs)) = \'GRAPHIC PRINT\' THEN \'Printed\' WHEN UPPER(TRIM(designs)) = \'ANIMAL PRINT\' THEN \'Printed\' ELSE \'Other\' END ELSE designs END AS designs_new, CASE WHEN UPPER(category) LIKE \'%T-SHIRTS%\' THEN CASE WHEN TRIM(LOWER(collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(collar_new)) = \'polo\' THEN \'Polo\' ELSE \'Others\' END ELSE collar_new END AS collar_new_modified, fit, CASE WHEN UPPER(STYLE) LIKE \'%LUXE%\' OR UPPER(sku_group) LIKE \'4MLX%\' OR UPPER(sku_group) LIKE \'4LRN%\' OR UPPER(sku_group) LIKE \'4LPL%\' OR UPPER(sku_group) LIKE \'4LTR%\' OR UPPER(sku_group) LIKE \'4LCH%\' OR UPPER(sku_group) LIKE \'4LJE%\' OR UPPER(sku_group) LIKE \'4LJK%\' OR UPPER(sku_group) LIKE \'4LSW%\' OR UPPER(sku_group) LIKE \'4LHD%\' OR UPPER(sku_group) LIKE \'4LOS%\' OR UPPER(sku_group) LIKE \'4LSHS%\' OR UPPER(sku_group) LIKE \'4LSFS%\' OR UPPER(sku_group) LIKE \'4LSH%\' OR UPPER(sku_group) LIKE \'4LBL%\' OR UPPER(sku_group) LIKE \'4LCA%\' OR UPPER(sku_group) LIKE \'4LSWT%\' OR UPPER(sku_group) LIKE \'4LCD%\' OR UPPER(sku_group) LIKE \'4LJO%\' THEN \'Luxe\' WHEN UPPER(STYLE) LIKE \'%PLUS%\' OR UPPER(sku_group) like \'%4BJ002%\' OR UPPER(sku_group) LIKE \'4MBG%\' OR UPPER(sku_group) LIKE \'4BRN%\' OR UPPER(sku_group) LIKE \'4BPL%\' OR UPPER(sku_group) LIKE \'4BTR%\' OR UPPER(sku_group) LIKE \'4BCH%\' OR UPPER(sku_group) LIKE \'4BJE%\' OR UPPER(sku_group) LIKE \'4BJK%\' OR UPPER(sku_group) LIKE \'4BSW%\' OR UPPER(sku_group) LIKE \'4BHD%\' OR UPPER(sku_group) LIKE \'4BOS%\' OR UPPER(sku_group) LIKE \'4BSHS%\' OR UPPER(sku_group) LIKE \'4BSFS%\' OR UPPER(sku_group) LIKE \'4BSH%\' OR UPPER(sku_group) LIKE \'4BBL%\' OR UPPER(sku_group) LIKE \'4BCA%\' OR UPPER(sku_group) LIKE \'4BSWT%\' OR UPPER(sku_group) LIKE \'4BCD%\' OR UPPER(sku_group) LIKE \'4BJO%\' THEN \'Plus\' when upper(sku_group) like \'MP%\' THEN \'MP\' ELSE \'Snitch\' END AS style, CASE WHEN TRIM(LOWER(sleeve_type)) IN (\'sleeveless\') THEN \'Sleeveless\' WHEN TRIM(LOWER(sleeve_type)) IN (\'half sleeve\',\'elbow sleeve\') THEN \'Half Sleeve\' WHEN TRIM(LOWER(sleeve_type)) IN (\'full sleeve\',\'three-quarter sleeves\') THEN \'Full Sleeve\' ELSE \'Others\' END AS sleeve_length, CASE WHEN LOWER(STYLE) LIKE \'%linen%\' THEN \'Linen\' WHEN MATERIAL_NEW = \'Cotton\' THEN \'Cotton\' WHEN MATERIAL_NEW IN (\'Tencel\', \'Tencil\', \'Polyester\', \'Terry\', \'Rayon\', \'Nylon\', \'Modal\', \'Others\') THEN \'Polyester\' WHEN MATERIAL_NEW = \'Linen\' THEN \'Linen\' ELSE \'Polyester\' END AS material FROM SNITCH_DB.MAPLEMONK.metafields_data ), offline_inv AS ( SELECT s.zone, UPPER(o.sku_group) AS sku_group, SUM(o.inventory) + SUM(o.jit_qty) AS offline_inventory, COUNT(DISTINCT CASE WHEN (o.inventory + o.jit_qty) > 0 THEN o.branch_code END) AS region_store_count FROM snitch_db.maplemonk.offline_master o JOIN ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ) s ON o.branch_code = s.branch_code GROUP BY 1, 2 ) SELECT a.warehouse_location, a.sku_group, COALESCE(a.product_name, m.product_name) AS product_name, a.category, a.sellable_inventory, COALESCE(off.offline_inventory, 0) AS offline_inventory, COALESCE(off.region_store_count, 0) AS region_store_count, m.designs_new AS designs, m.collar_new_modified AS collar_new, m.fit, CASE WHEN UPPER(CATEGORY) IN (\'BAGS\',\'BELTS\',\'ACCESSORIES\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\') THEN \'Long_Tail\' WHEN UPPER(a.sku_group) LIKE \'4MLX%\' OR UPPER(a.sku_group) LIKE \'4LRN%\' OR UPPER(a.sku_group) LIKE \'4LPL%\' OR UPPER(a.sku_group) LIKE \'4LTR%\' OR UPPER(a.sku_group) LIKE \'4LCH%\' OR UPPER(a.sku_group) LIKE \'4LJE%\' OR UPPER(a.sku_group) LIKE \'4LJK%\' OR UPPER(a.sku_group) LIKE \'4LSW%\' OR UPPER(a.sku_group) LIKE \'4LHD%\' OR UPPER(a.sku_group) LIKE \'4LOS%\' OR UPPER(a.sku_group) LIKE \'4LSHS%\' OR UPPER(a.sku_group) LIKE \'4LSFS%\' OR UPPER(a.sku_group) LIKE \'4LSH%\' OR UPPER(a.sku_group) LIKE \'4LBL%\' OR UPPER(a.sku_group) LIKE \'4LCA%\' OR UPPER(a.sku_group) LIKE \'4LSWT%\' OR UPPER(a.sku_group) LIKE \'4LCD%\' OR UPPER(a.sku_group) LIKE \'4LJO%\' THEN \'Luxe\' WHEN UPPER(a.sku_group) LIKE \'4MBG%\' OR UPPER(a.sku_group) like \'%4BJ002%\' OR UPPER(a.sku_group) LIKE \'4BRN%\' OR UPPER(a.sku_group) LIKE \'4BPL%\' OR UPPER(a.sku_group) LIKE \'4BTR%\' OR UPPER(a.sku_group) LIKE \'4BCH%\' OR UPPER(a.sku_group) LIKE \'4BJE%\' OR UPPER(a.sku_group) LIKE \'4BJK%\' OR UPPER(a.sku_group) LIKE \'4BSW%\' OR UPPER(a.sku_group) LIKE \'4BHD%\' OR UPPER(a.sku_group) LIKE \'4BOS%\' OR UPPER(a.sku_group) LIKE \'4BSHS%\' OR UPPER(a.sku_group) LIKE \'4BSFS%\' OR UPPER(a.sku_group) LIKE \'4BSH%\' OR UPPER(a.sku_group) LIKE \'4BBL%\' OR UPPER(a.sku_group) LIKE \'4BCA%\' OR UPPER(a.sku_group) LIKE \'4BSWT%\' OR UPPER(a.sku_group) LIKE \'4BCD%\' OR UPPER(a.sku_group) LIKE \'4BJO%\' THEN \'Plus\' WHEN UPPER(a.sku_group) LIKE \'MP%\' THEN \'MP\' ELSE \'Snitch\' END AS style, m.material, CASE WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category NOT IN (\'Collection\',\'Online NOOS\') ) THEN \'EOSS\' WHEN UPPER(a.sku_group) IN ( SELECT DISTINCT UPPER(\"SKU Group\") FROM snitch_db.maplemonk.final_discount_skus_sheet1 WHERE category IN (\'Collection\')) THEN \'Collection\' ELSE \'Fresh\' END AS allocation_status, m.sleeve_length, a.live_date, pi.image_url AS image_link, CASE WHEN UPPER(A.SKU_GROUP) LIKE \'4MSFR%\' THEN ROUND(((A.SELLABLE_INVENTORY-2)/12),0) WHEN UPPER(A.SKU_GROUP) LIKE \'SN%\' THEN ROUND(((A.SELLABLE_INVENTORY-1)/4),0) WHEN UPPER(A.SKU_GROUP) LIKE \'BP%\' THEN ROUND(((A.SELLABLE_INVENTORY-1)/3),0) WHEN UPPER(A.SKU_GROUP) LIKE \'4MCP%\' THEN ROUND(((A.SELLABLE_INVENTORY-1)/3),0) WHEN UPPER(A.SKU_GROUP) LIKE \'SH0%\' THEN GREATEST(LEAST( ROUND((a.S_UNITS - 1) / 2), ROUND((a.M_UNITS - 1) / 2), ROUND((a.L_UNITS - 1) / 2), ROUND((a.XL_UNITS - 1) / 2) ), 0) WHEN UPPER(A.SKU_GROUP) LIKE \'4MBL%\' THEN GREATEST(LEAST( ROUND((a.M_UNITS - 1) / 2), ROUND((a.XL_UNITS - 1) / 2), ROUND((a.XL3_UNITS - 1) / 2) ), 0) WHEN UPPER(a.sku_group) LIKE \'4MBG%\' OR UPPER(a.sku_group) like \'%4BJ002%\' OR UPPER(a.sku_group) LIKE \'4BRN%\' OR UPPER(a.sku_group) LIKE \'4BPL%\' OR UPPER(a.sku_group) LIKE \'4BTR%\' OR UPPER(a.sku_group) LIKE \'4BCH%\' OR UPPER(a.sku_group) LIKE \'4BJE%\' OR UPPER(a.sku_group) LIKE \'4BJK%\' OR UPPER(a.sku_group) LIKE \'4BSW%\' OR UPPER(a.sku_group) LIKE \'4BHD%\' OR UPPER(a.sku_group) LIKE \'4BOS%\' OR UPPER(a.sku_group) LIKE \'4BSHS%\' OR UPPER(a.sku_group) LIKE \'4BSFS%\' OR UPPER(a.sku_group) LIKE \'4BSH%\' OR UPPER(a.sku_group) LIKE \'4BBL%\' OR UPPER(a.sku_group) LIKE \'4BCA%\' OR UPPER(a.sku_group) LIKE \'4BSWT%\' OR UPPER(a.sku_group) LIKE \'4BCD%\' OR UPPER(a.sku_group) LIKE \'4BJO%\' THEN GREATEST(LEAST( ROUND((a.XL3_UNITS - 1) / 3), ROUND((a.XL4_UNITS - 1) / 3), ROUND((a.XL5_UNITS - 1) / 2), ROUND((a.XL6_UNITS - 1) / 2) ), 0) WHEN UPPER(a.category) LIKE \'%JEANS%\' AND COALESCE(m.style, \'Snitch\') <> \'Plus\' THEN CASE WHEN GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) > 0 THEN GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) ELSE GREATEST( LEAST( ROUND((a.xs_units - 1) / 2), ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4) ), LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), LEAST( ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3), ROUND((a.xxl_units - 1) / 2) ), 0 ) END ELSE GREATEST(LEAST( ROUND((a.s_units - 1) / 3), ROUND((a.m_units - 1) / 4), ROUND((a.l_units - 1) / 4), ROUND((a.xl_units - 1) / 3) ), 0) END AS full_size_options, a.xs_units, a.s_units, a.m_units, a.l_units, a.xl_units, a.xxl_units, a.xl3_units, a.xl4_units, a.xl5_units, a.xl6_units, a.xl7_units, a.xl8_units FROM SNITCH_DB.MAPLEMONK.availability_master_v2_merged a LEFT JOIN metafields_std m ON a.sku_group = m.sku_group LEFT JOIN product_images pi ON a.sku_group = pi.sku_group LEFT JOIN offline_inv off ON UPPER(a.warehouse_location) = UPPER(off.zone) AND UPPER(a.sku_group) = off.sku_group WHERE a.sellable_inventory > 0 AND a.sku_group NOT LIKE \'%_T\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            